#include <cstddef>
#include <cstdint>
extern "C" std::int64_t fifocache(const std::int64_t*a,std::size_t n,std::uint8_t*out,std::size_t cap) noexcept {if(!a||n<2||n>26)return -1;auto c=a[0],ops=a[1];if(c<1||c>6||ops<0||ops>8||n!=2+3*static_cast<std::size_t>(ops))return -1;std::int64_t k[6],v[6];std::size_t z=0;int hits=0,miss=0,g=0;std::uint8_t q[8];for(std::size_t i=0;i<static_cast<std::size_t>(ops);i++){auto op=a[2+3*i],key=a[3+3*i],val=a[4+3*i];if(key<0||key>15||(op!=0&&op!=1))return -1;if(op==0){if(val<0||val>255)return -1;std::size_t j=0;while(j<z&&k[j]!=key)j++;if(j<z){for(auto t=j+1;t<z;t++){k[t-1]=k[t];v[t-1]=v[t];}z--;}if(z==static_cast<std::size_t>(c)){for(auto t=1u;t<z;t++){k[t-1]=k[t];v[t-1]=v[t];}z--;}k[z]=key;v[z++]=val;}else{if(val!=0)return -1;std::size_t j=0;while(j<z&&k[j]!=key)j++;if(j<z){hits++;q[g++]=static_cast<std::uint8_t>(v[j]);}else{miss++;q[g++]=255;}}}auto need=4+g+2*z;if(!out||cap<need)return -2;out[0]=hits;out[1]=miss;out[2]=z;out[3]=g;for(std::size_t i=0;i<g;i++)out[4+i]=q[i];for(std::size_t i=0;i<z;i++){out[4+g+2*i]=k[i];out[5+g+2*i]=v[i];}return need;}
